"""Отчет ЛР2-3, расширение: качество трафика, каналы по сайтам, контрольные перечни, журнал фиксации Similarweb,
ориентиры стоимости клика, перечень файлов. Все числа берутся из снимка Similarweb (csv) и из результатов расчета."""
import csv
import json
from pathlib import Path

from rep_common import H, P, num, pct, table, figure, A, X
from inputs import *

ROOT = Path(__file__).resolve().parent.parent
sw = load_sw()
sw_raw = {r["domain"]: r for r in csv.DictReader(open(ROOT / "Материалы_собранные" / "similarweb_снимок_2026-10-03.csv", encoding="utf-8-sig"), delimiter=";")}


def _sec(t):
    h, m, s = (t.split(":") + ["0", "0"])[:3] if t.count(":") == 2 else ("0", *t.split(":"))
    return int(h) * 3600 + int(m) * 60 + int(s)


def _f(v):
    return float(v) if v not in ("", None) else None


def quality():
    rows = []
    for r in sorted(sw, key=lambda r: -r["visits_month"]):
        d = sw_raw[r["domain"]]
        rows.append([r["name"], d["duration"], num(_f(d["pages_visit"]), 2), num(_f(d["bounce_pct"]), 1) + " %" if d["bounce_pct"] else "н/д",
                     num(_f(d["desktop_pct"]), 1) + " %", num(_f(d["global_rank"]), 0)])
    table("quality", "Качество трафика сайтов: длительность визита, глубина просмотра, отказы и доля настольных устройств",
          ["Сайт", "Длительность визита", "Страниц за визит", "Доля отказов", "Доля настольных устройств", "Мировой ранг"], rows,
          "Метрики вовлеченности дополняют объем трафика: они показывают, пришел ли посетитель решать задачу или быстро ушел. Дольше всех на сайте остаются посетители Datarails (3 минуты 19 секунд, 3,86 страницы за визит), то есть платформа с длинным циклом продажи удерживает внимание. У AI-помощников визит короткий (около 30 секунд при 1,8-3,1 страницы): пользователь приходит за одной формулой и уходит. Специализированные инструменты проверки (PerfectXL, Arixcel, Operis) держат посетителя 26-31 секунду при отказах 39-69 %, что типично для узких информационных сайтов малого размера. Для TableMind вывод практический: на странице продукта нужно донести ценность за полминуты, а длительные сценарии (демонстрация, отчет примера) выносить на отдельные страницы.")
    d = lambda k, name: next(r for r in sw if r["domain"] == k)["ch"]
    ch_rows = []
    for r in sorted(sw, key=lambda r: -r["visits_month"]):
        c = r["ch"]
        ch_rows.append([r["name"], pct(c["direct"], 1), pct(c["org_search"], 1), pct(c["paid_search"], 1), pct(c["referrals"], 1),
                        pct(c["org_social"] + c["paid_social"], 1), pct(c["display"], 1), pct(c["gen_ai"], 1)])
    best_ai = max(sw, key=lambda r: r["ch"]["gen_ai"])
    table("channels_site", "Структура каналов трафика по сайтам, % визитов",
          ["Сайт", "Прямые заходы", "Органический поиск", "Платный поиск", "Рефералы", "Соцсети", "Медийная реклама", "Генеративный ИИ"], ch_rows,
          f"Таблица раскрывает данные рисунка [[f:channels]] по каждому сайту. Органический поиск доминирует у AI-помощников (Rows, Numerous.ai, Formula Bot, Ajelix: 53-58 %), прямые заходы у Datarails и Shortcut (59 % и 56 %), то есть у брендов с узнаваемостью. Канал генеративного ИИ как источник визитов пока мал: максимум {pct(best_ai['ch']['gen_ai'], 1)} у сайта {best_ai['name']}, но он уже отделен Similarweb в самостоятельную категорию и заслуживает наблюдения в проекте: ответы AI-ассистентов начинают направлять пользователей на инструменты проверки. Платный поиск почти не используется специализированными игроками (до 4,3 %), кроме Datarails (11,6 %), что подтверждает вывод ЛР4 о слабой отдаче платной рекламы на узком рынке.")

    figure("quality", "Рисунки/07_качество_трафика.png", "Объем и качество трафика сайтов: визиты и длительность визита",
           "Диаграмма разделяет сайты по двум признакам одновременно. AI-помощники Rows, Numerous.ai и Ajelix собирают много визитов длительностью около 30 секунд; у Julius AI и Shortcut визит длиннее 80 секунд, а у Datarails около 3 минут 20 секунд, то есть аудитория пришла за решением сложной задачи. Малые специализированные сайты находятся в левой части и по длительности визита не отличаются от массовых помощников; их преимущество не в вовлеченности, а в точном попадании в задачу.")
    geo_rows = []
    for r in sorted(sw, key=lambda r: -r["visits_month"]):
        cells = [f"{c} {num(v * 100, 1)} %" for c, v in r["top"]]
        cells += ["-"] * (5 - len(cells))
        geo_rows.append([r["name"]] + cells + [pct(r["geo_share"], 1)])
    table("geo_site", "Топ-5 стран по визитам каждого сайта и доля целевых стран",
          ["Сайт", "1-я страна", "2-я страна", "3-я страна", "4-я страна", "5-я страна", "Доля целевых стран"], geo_rows,
          "Таблица показывает основу расчета доли целевых стран в таблице [[t:sw_rel]]. Целевыми считаются США, Великобритания, Канада, Австралия, Ирландия и страны ЕС; Индия, Бразилия, Индонезия, Нигерия и другие страны за границами проекта в долю не входят. Сильнее всего на целевые страны ориентированы Operis (Великобритания 59 %), Datarails (США 69 %) и Spreadsheet Detective (США и Великобритания 89 %), а у Julius AI, Formula Bot и Rows доля целевых стран около 10 %, поэтому их большой трафик почти не относится к рынку проекта. Список стран ограничен пятью первыми, поэтому доли целевых стран нижняя оценка.")
    figure("geo_fig", "Рисунки/08_география_сайтов.png", "Доля визитов из целевых стран, прочих стран топ-5 и остальных стран",
           "На диаграмме видно, насколько трафик сайта относится к рынку проекта: у Operis, Datarails и Spreadsheet Detective зеленая часть занимает большую долю, а у AI-помощников с массовой аудиторией в развивающихся странах она мала. Серая и светлая части - трафик, который в расчет рынка проекта не входит.")


